package com.butusun.writing;
import android.app.*;import android.os.*;import android.webkit.*;import android.content.*;import android.net.Uri;import java.io.*;import java.net.*;import javax.net.ssl.HttpsURLConnection;import java.security.*;import java.util.*;import org.json.*;

public class MainActivity extends Activity {
 private WebView web; private File active; private String exportPending; private ValueCallback<Uri[]> chooser; private boolean checking=false;
 private static final String ORIGIN="https://butusun.github.io/english-learning-journal/mobile/";
 private static final String RAW="https://raw.githubusercontent.com/ButuSun/english-learning-journal/main/mobile/";
 private static final String[] FILES={"index.html","app.js","style.css","data.json"};
 @Override public void onCreate(Bundle b){super.onCreate(b);getWindow().setStatusBarColor(0xffedf0e8);getWindow().setNavigationBarColor(0xfffcfdf8);getWindow().getDecorView().setSystemUiVisibility(android.view.View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR);
 String version=getPreferences(0).getString("bundle","");if(version.matches("[a-f0-9]{64}")){File f=new File(getFilesDir(),"bundle-"+version);boolean ok=true;for(String n:FILES)if(!new File(f,n).isFile())ok=false;if(ok)active=f;}
 web=new WebView(this);setContentView(web);WebSettings s=web.getSettings();s.setJavaScriptEnabled(true);s.setDomStorageEnabled(true);s.setAllowFileAccess(false);s.setAllowContentAccess(true);s.setMixedContentMode(WebSettings.MIXED_CONTENT_NEVER_ALLOW);s.setSupportZoom(false);s.setSafeBrowsingEnabled(true);
 web.addJavascriptInterface(new Bridge(),"JournalNative");
 web.setWebViewClient(new WebViewClient(){
 @Override public boolean shouldOverrideUrlLoading(WebView w,WebResourceRequest r){String u=r.getUrl().toString();if(u.equals(ORIGIN)||u.equals(ORIGIN+"index.html"))return false;if(r.isForMainFrame()&&"https".equals(r.getUrl().getScheme())){try{startActivity(new Intent(Intent.ACTION_VIEW,r.getUrl()));}catch(Exception e){}}return true;}
 @Override public WebResourceResponse shouldInterceptRequest(WebView w,WebResourceRequest r){String u=r.getUrl().toString().split("\\?")[0];if(u.startsWith(ORIGIN)){String n=u.substring(ORIGIN.length());if(n.isEmpty())n="index.html";boolean known=false;for(String k:FILES)if(k.equals(n))known=true;if(!known)return new WebResourceResponse("text/plain","UTF-8",new ByteArrayInputStream(new byte[0]));try{InputStream in=active==null?getAssets().open(n):new FileInputStream(new File(active,n));String mime=n.endsWith("html")?"text/html":n.endsWith("js")?"application/javascript":n.endsWith("css")?"text/css":"application/json";Map<String,String> h=new HashMap<>();h.put("Cache-Control","no-store");h.put("Content-Security-Policy","default-src 'none'; script-src 'self'; style-src 'self' 'unsafe-inline'; connect-src 'self' https://raw.githubusercontent.com; img-src 'self' data:; frame-src 'none'; object-src 'none'; base-uri 'none'");return new WebResourceResponse(mime,"UTF-8",200,"OK",h,in);}catch(Exception e){return new WebResourceResponse("text/plain","UTF-8",new ByteArrayInputStream(new byte[0]));}}if(u.startsWith(RAW))return null;return new WebResourceResponse("text/plain","UTF-8",new ByteArrayInputStream(new byte[0]));}
 });
 web.setWebChromeClient(new WebChromeClient(){@Override public boolean onShowFileChooser(WebView w,ValueCallback<Uri[]> cb,FileChooserParams p){if(chooser!=null)chooser.onReceiveValue(null);chooser=cb;Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("application/json");i.addCategory(Intent.CATEGORY_OPENABLE);try{startActivityForResult(i,22);}catch(Exception e){chooser.onReceiveValue(null);chooser=null;}return true;}});
 web.loadUrl(ORIGIN+"index.html");check(false);
 }
 private void notice(String text){runOnUiThread(()->{if(web!=null)web.evaluateJavascript("window.onNativeUpdate&&window.onNativeUpdate("+JSONObject.quote(text)+")",null);});}
 public class Bridge {
 @JavascriptInterface public void copyText(String text){if(text==null||text.length()>2000000)return;runOnUiThread(()->{android.content.ClipboardManager c=(android.content.ClipboardManager)getSystemService(CLIPBOARD_SERVICE);c.setPrimaryClip(ClipData.newPlainText("写作日历",text));});}
 @JavascriptInterface public void exportBackup(String text){if(text==null||text.length()>10000000)return;runOnUiThread(()->{exportPending=text;Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.setType("application/json");i.addCategory(Intent.CATEGORY_OPENABLE);i.putExtra(Intent.EXTRA_TITLE,"writing-backup-"+new java.text.SimpleDateFormat("yyyyMMdd",Locale.ROOT).format(new Date())+".json");try{startActivityForResult(i,21);}catch(Exception e){notice("未能打开保存窗口，请复制草稿备份");}});}
 @JavascriptInterface public void checkUpdate(){check(true);}
 }
 private byte[] download(String url)throws Exception{HttpsURLConnection c=(HttpsURLConnection)new URL(url).openConnection();c.setConnectTimeout(12000);c.setReadTimeout(12000);c.setInstanceFollowRedirects(false);try{if(c.getResponseCode()!=200)throw new IOException("http");try(InputStream in=c.getInputStream();ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1){out.write(b,0,n);if(out.size()>10000000)throw new IOException("large");}return out.toByteArray();}}finally{c.disconnect();}}
 private String hash(byte[] bytes)throws Exception{byte[] h=MessageDigest.getInstance("SHA-256").digest(bytes);StringBuilder s=new StringBuilder();for(byte b:h)s.append(String.format(Locale.ROOT,"%02x",b&255));return s.toString();}
 private synchronized void check(boolean manual){if(checking)return;checking=true;new Thread(()->{try{
 JSONObject manifest=new JSONObject(new String(download(RAW+"version.json?t="+System.currentTimeMillis()),"UTF-8"));String id=manifest.getString("bundle");if(!id.matches("[a-f0-9]{64}"))throw new IOException("id");int min=manifest.optInt("minNativeVersion",1);if(min>1||manifest.optInt("apkVersionCode",1)>1){String url=manifest.optString("apkUrl","");if(url.startsWith("https://github.com/ButuSun/english-learning-journal/releases/download/")){runOnUiThread(()->new AlertDialog.Builder(this).setTitle("有新的安装包").setMessage("覆盖安装可保留草稿。是否打开下载页面？").setPositiveButton("下载更新",(d,w)->startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse(url)))).setNegativeButton("稍后",null).show());}else if(manual)notice("新版本需要更新安装包，请查看项目发布页");if(min>1)return;}
 String current=getPreferences(0).getString("bundle","");String embedded;try(InputStream in=getAssets().open("version.json")){ByteArrayOutputStream o=new ByteArrayOutputStream();byte[] b=new byte[4096];int n;while((n=in.read(b))!=-1)o.write(b,0,n);embedded=new JSONObject(o.toString("UTF-8")).getString("bundle");}
 if(id.equals(current)||current.isEmpty()&&id.equals(embedded)){if(manual)notice("当前已是最新版本");return;}
 JSONObject checks=manifest.getJSONObject("files");File stage=new File(getFilesDir(),"bundle-"+id);stage.mkdirs();for(String n:FILES){byte[] bytes=download(RAW+n+"?v="+id);if(!hash(bytes).equals(checks.getString(n)))throw new IOException("checksum");try(FileOutputStream out=new FileOutputStream(new File(stage,n))){out.write(bytes);out.getFD().sync();}}
 if(!getPreferences(0).edit().putString("bundle",id).commit())throw new IOException("save");notice("新版界面已下载，下次启动生效；草稿已保留");
 }catch(Exception e){if(manual)notice("暂时无法检查更新，当前版本仍可离线使用");}finally{synchronized(MainActivity.this){checking=false;}}}).start();}
 @Override protected void onActivityResult(int request,int result,Intent intent){super.onActivityResult(request,result,intent);if(request==22&&chooser!=null){chooser.onReceiveValue(result==RESULT_OK&&intent!=null?new Uri[]{intent.getData()}:null);chooser=null;}if(request==21&&result==RESULT_OK&&intent!=null&&exportPending!=null){try(OutputStream o=getContentResolver().openOutputStream(intent.getData())){o.write(exportPending.getBytes("UTF-8"));notice("草稿备份已导出");}catch(Exception e){notice("导出失败，请重试");}}exportPending=null;}
 @Override public void onBackPressed(){web.evaluateJavascript("if(document.querySelector('#sheet').open){document.querySelector('#sheet').close()}else if(detail||page!=='calendar'){nav('calendar')}else{true}",result->{if("true".equals(result))moveTaskToBack(true);});}
 @Override protected void onDestroy(){if(chooser!=null)chooser.onReceiveValue(null);super.onDestroy();}
}
